import json, sys

def short(s, n=300):
    s = str(s)
    if len(s) > n:
        return s[:n] + f"...[{len(s)}chars]"
    return s

def summarize_content(content):
    out = []
    if isinstance(content, str):
        out.append(("text", short(content, 500)))
        return out
    if isinstance(content, list):
        for c in content:
            if not isinstance(c, dict):
                out.append(("?", short(c)))
                continue
            t = c.get("type")
            if t == "text":
                out.append(("text", short(c.get("text",""), 500)))
            elif t == "tool_use":
                name = c.get("name")
                inp = c.get("input", {})
                inp_str = short(json.dumps(inp), 300)
                out.append(("tool_use", f"{name} {inp_str}"))
            elif t == "tool_result":
                cont = c.get("content")
                if isinstance(cont, list):
                    text = " ".join(short(x.get("text",""),200) for x in cont if isinstance(x,dict) and x.get("type")=="text")
                else:
                    text = short(cont, 200)
                err = c.get("is_error")
                out.append(("tool_result", f"err={err} len={len(json.dumps(cont)) if cont else 0} :: {text}"))
            else:
                out.append((t, short(c, 200)))
    return out

def main(path):
    with open(path) as f:
        for i, line in enumerate(f):
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception as e:
                print(f"[{i}] PARSE ERROR {e}")
                continue
            ts = obj.get("timestamp", "")
            typ = obj.get("type", obj.get("role",""))
            msg = obj.get("message", obj)
            role = msg.get("role") if isinstance(msg, dict) else None
            content = msg.get("content") if isinstance(msg, dict) else None
            print(f"--- [{i}] ts={ts} type={typ} role={role}")
            if content is not None:
                for kind, txt in summarize_content(content):
                    print(f"    {kind}: {txt}")
            else:
                print(f"    (raw) {short(obj, 300)}")

if __name__ == "__main__":
    main(sys.argv[1])

